function getTableStatus(table) {
  const now = Date.now();
  const unpaidAt = Date.parse(table.last_unpaid_order_at || "");
  const activityAt = Date.parse(table.last_order_at || table.created_at || "");
  if (Number.isFinite(unpaidAt)) return now - unpaidAt < 3600000 ? "dining" : "payment";
  if (Number.isFinite(activityAt) && now - activityAt >= 31 * 24 * 60 * 60 * 1000) return "inactive";
  return "available";
}
